49	/**
50	 * Global Exception handler for REST controllers.
51	 * <p>
52	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
53	 *
54	 * @author Vitaliy Fedoriv
55	 * @author Alexander Dudkin
56	 */
57	@ControllerAdvice
58	public class ExceptionControllerAdvice {
59	
60	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
61	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
62	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
63	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
64	
65	    /**
66	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
67	     * class.
68	     *
69	     * @param e     Object referring to the thrown exception.
70	     * @param status HTTP response status.
71	     * @param url URL request.
72	     */
73	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
74	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
75	        problemDetail.setType(URI.create(url.toString()));
76	        problemDetail.setTitle(e.getClass().getSimpleName());
77	        problemDetail.setDetail(detail);
78	        problemDetail.setProperty("timestamp", Instant.now());
79	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
80	        return problemDetail;
81	    }
82	
83	    /**
84	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
85	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
86	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
87	     * would catch it and report an authorization failure as a 500.
88	     *
89	     * @param e The {@link AccessDeniedException} to propagate
90	     * @throws AccessDeniedException always
91	     */
92	    @ExceptionHandler(AccessDeniedException.class)
93	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
94	        throw e;
95	    }
96	
97	    /**
98	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
99	     *
100	     * @param e The {@link Exception} to be handled
101	     * @param request {@link HttpServletRequest} object referring to the current request.
102	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
103	     */
104	    @ExceptionHandler(Exception.class)
105	    @ResponseBody
106	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
107	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
108	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
109	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
110	        return ResponseEntity.status(status).body(detail);
111	    }
112	
113	    /**
114	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
115	     * method returns a 404 Not Found status if an entity does not exist.
116	     *
117	     * @param e The {@link DataIntegrityViolationException} to be handled
118	     * @param request {@link HttpServletRequest} object referring to the current request.
119	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
120	     */
121	    @ExceptionHandler(DataIntegrityViolationException.class)
122	    @ResponseBody
123	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
124	        logger.warn("Data integrity violation at {} {}: {}",
125	            request.getMethod(),
126	            request.getRequestURI(),
127	            e.getMessage());
128	        logger.debug("Data integrity violation stacktrace", e);
129	        HttpStatus status = HttpStatus.NOT_FOUND;
130	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
131	        return ResponseEntity.status(status).body(detail);
132	    }
133	
134	    /**
135	     * Handles {@link InvalidTelephoneException} thrown while normalizing a telephone number into
136	     * E.164 form, returning a 400 Bad Request so a number that cannot form a valid E.164 value is
137	     * rejected rather than surfacing as an unexpected 500.
138	     *
139	     * @param e The {@link InvalidTelephoneException} to be handled
140	     * @param request {@link HttpServletRequest} object referring to the current request.
141	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
142	     */
143	    @ExceptionHandler(InvalidTelephoneException.class)
144	    @ResponseBody
145	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
146	        logger.debug("Invalid telephone at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
147	        HttpStatus status = HttpStatus.BAD_REQUEST;
148	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
149	        return ResponseEntity.status(status).body(detail);
150	    }
151	
152	    /**
153	     * Handles {@link InvalidPostcodeException} thrown when a supplied postcode is out of range for
154	     * the owner's city's region, returning a 400 Bad Request so an invalid postcode is rejected
155	     * rather than surfacing as an unexpected 500.
156	     *
157	     * @param e The {@link InvalidPostcodeException} to be handled
158	     * @param request {@link HttpServletRequest} object referring to the current request.
159	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
160	     */
161	    @ExceptionHandler(InvalidPostcodeException.class)
162	    @ResponseBody
163	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
164	        logger.debug("Invalid postcode at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
165	        HttpStatus status = HttpStatus.BAD_REQUEST;
166	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
167	        return ResponseEntity.status(status).body(detail);
168	    }
169	
170	    /**
171	     * Handles {@link InvalidAddressException} thrown when an owner request supplies no usable
172	     * postal address in either accepted form (neither a non-blank structured {@code addressLine1}
173	     * nor a non-blank flat {@code address}), returning a 400 Bad Request so a missing address is
174	     * rejected rather than surfacing as an unexpected 500.
175	     *
176	     * @param e The {@link InvalidAddressException} to be handled
177	     * @param request {@link HttpServletRequest} object referring to the current request.
178	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
179	     */
180	    @ExceptionHandler(InvalidAddressException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleInvalidAddressException(InvalidAddressException e, HttpServletRequest request) {
183	        logger.debug("Invalid address at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
184	        HttpStatus status = HttpStatus.BAD_REQUEST;
185	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
186	        return ResponseEntity.status(status).body(detail);
187	    }
188	
189	    /**
190	     * Handles {@link DisposableEmailException} thrown when a supplied email address belongs to a
191	     * disposable-email domain on the blocklist, returning a 400 Bad Request so a disposable email
192	     * is rejected rather than surfacing as an unexpected 500.
193	     *
194	     * @param e The {@link DisposableEmailException} to be handled
195	     * @param request {@link HttpServletRequest} object referring to the current request.
196	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
197	     */
198	    @ExceptionHandler(DisposableEmailException.class)
199	    @ResponseBody
200	    public ResponseEntity<ProblemDetail> handleDisposableEmailException(DisposableEmailException e, HttpServletRequest request) {
201	        logger.debug("Disposable email at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
202	        HttpStatus status = HttpStatus.BAD_REQUEST;
203	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
204	        return ResponseEntity.status(status).body(detail);
205	    }
