207	    /**
208	     * Handles {@link InvalidRegistrationDateException} thrown when a supplied registration date is
209	     * later than the server's current date, returning a 400 Bad Request so a future-dated
210	     * registration is rejected rather than surfacing as an unexpected 500.
211	     *
212	     * @param e The {@link InvalidRegistrationDateException} to be handled
213	     * @param request {@link HttpServletRequest} object referring to the current request.
214	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
215	     */
216	    @ExceptionHandler(InvalidRegistrationDateException.class)
217	    @ResponseBody
218	    public ResponseEntity<ProblemDetail> handleInvalidRegistrationDateException(InvalidRegistrationDateException e, HttpServletRequest request) {
219	        logger.debug("Invalid registration date at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
220	        HttpStatus status = HttpStatus.BAD_REQUEST;
221	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
222	        return ResponseEntity.status(status).body(detail);
223	    }
224	
225	    /**
226	     * Handles {@link RegistrationRateLimitException} thrown when the per-day owner registration
227	     * limit has been reached, returning a 429 Too Many Requests with an RFC7807 problem body.
228	     *
229	     * @param e The {@link RegistrationRateLimitException} to be handled
230	     * @param request {@link HttpServletRequest} object referring to the current request.
231	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
232	     */
233	    @ExceptionHandler(RegistrationRateLimitException.class)
234	    @ResponseBody
235	    public ResponseEntity<ProblemDetail> handleRegistrationRateLimitException(RegistrationRateLimitException e, HttpServletRequest request) {
236	        logger.debug("Registration rate limit at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
237	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
238	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
239	        return ResponseEntity.status(status).body(detail);
240	    }
241	
242	    /**
243	     * Handles {@link DuplicateOwnerException} thrown when a new owner's identity key matches an
244	     * existing, non-deleted owner, returning a 409 Conflict with an RFC7807 problem body.
245	     *
246	     * @param e The {@link DuplicateOwnerException} to be handled
247	     * @param request {@link HttpServletRequest} object referring to the current request.
248	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
249	     */
250	    @ExceptionHandler(DuplicateOwnerException.class)
251	    @ResponseBody
252	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
253	        logger.debug("Duplicate owner at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
254	        HttpStatus status = HttpStatus.CONFLICT;
255	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
256	        return ResponseEntity.status(status).body(detail);
257	    }
258	
259	    /**
260	     * Handles {@link CityCapacityException} thrown when an owner's city has reached its
261	     * registration capacity, returning a 409 Conflict with an RFC7807 problem body.
262	     *
263	     * @param e The {@link CityCapacityException} to be handled
264	     * @param request {@link HttpServletRequest} object referring to the current request.
265	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
266	     */
267	    @ExceptionHandler(CityCapacityException.class)
268	    @ResponseBody
269	    public ResponseEntity<ProblemDetail> handleCityCapacityException(CityCapacityException e, HttpServletRequest request) {
270	        logger.debug("City capacity reached at {} {}: {}", request.getMethod(), request.getRequestURI(), e.getMessage());
271	        HttpStatus status = HttpStatus.CONFLICT;
272	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
273	        return ResponseEntity.status(status).body(detail);
274	    }
275	
276	    /**
277	     * Handles exception thrown by Bean Validation on controller methods parameters
278	     *
279	     * @param e The {@link MethodArgumentNotValidException} to be handled
280	     * @param request {@link HttpServletRequest} object referring to the current request.
281	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
282	     */
283	    @ExceptionHandler(MethodArgumentNotValidException.class)
284	    @ResponseBody
285	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
286	        HttpStatus status = HttpStatus.BAD_REQUEST;
287	        BindingErrorsResponse errors = new BindingErrorsResponse();
288	        BindingResult bindingResult = e.getBindingResult();
289	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
290	        if (bindingResult.hasErrors()) {
291	            errors.addAllErrors(bindingResult);
292	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
293	                .map(FieldError::getField)
294	                .distinct()
295	                .toList();
296	            detail.setProperty("errors", invalidFields);
297	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
298	                .map(fieldError -> {
299	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
300	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
301	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
302	                        fieldError.getField(),
303	                        defaultMessage,
304	                        rejectedValue);
305	                    return new ValidationMessageDto(message)
306	                        .putAdditionalProperty("field", fieldError.getField())
307	                        .putAdditionalProperty("rejectedValue", rejectedValue)
308	                        .putAdditionalProperty("defaultMessage", defaultMessage);
309	                })
310	                .toList();
311	            logger.debug("Validation error at {} {}: {}",
312	                request.getMethod(),
313	                request.getRequestURI(),
314	                bindingResult.getFieldErrors());
315	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
316	            return ResponseEntity.status(status).body(detail);
317	        }
318	        return ResponseEntity.status(status).body(detail);
319	    }
320	
321	}
